local E=function(Z)local P,o=Z[#Z],""for I=1,#P,1 do o=o..P[Z[I]]end return o end local Z={}local P=0 local o=40 local function I(I,b,M)local E=Z[I]local n=b*M if P+n>o then return false,"too heavy: "..I end if E==nil then E={weight=b,quantity=0}Z[I]=E end E.quantity=E.quantity+M P=P+n return true end local function b(o,I)local b=Z[o]if b==nil or b.quantity<I then return false,"not enough "..o end b.quantity=b.quantity-I P=P-b.weight*I if b.quantity==0 then Z[o]=nil end return true end local function M()local o={}for Z in pairs(Z)do o[#o+1]=Z end table.sort(o)for P,o in ipairs(o)do local I=Z[o]print(o..(" x"..(I.quantity..(" ("..(I.weight*I.quantity.."kg)")))))end print("total weight: "..P)end print(I("rope",3,2))print(I("lantern",5,1))print(I("anvil",30,2))print(b("rope",1))print(b("sword",1))M()